import{_ as t,o as n,c as o,a3 as s}from"./chunks/framework.Ch_0qWu9.js";const h=JSON.parse('{"title":"Browser nested-component materials","description":"","frontmatter":{"sourcePath":"assets/environments/lean-base/browser-components/README.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/assets/environments/lean-base/browser-components/README.md","alternateUrl":"/TCSExam/docs/zh/environments/lean-base/browser-components/","alternateAnchors":{"browser-nested-component-materials":"browser-nested-component-materials","expat":"expat","emscripten":"emscripten","penrose-optimizer":"penrose-optimizer","obtain-sources-and-retain-notices":"obtain-sources-and-retain-notices"}},"headers":[],"relativePath":"environments/lean-base/browser-components/index.md","filePath":"environments/lean-base/browser-components/index.md"}'),r={name:"environments/lean-base/browser-components/index.md"};function a(i,e,c,d,p,l){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="browser-nested-component-materials" tabindex="-1">Browser nested-component materials <a class="header-anchor" href="#browser-nested-component-materials" aria-label="Permalink to &quot;Browser nested-component materials&quot;">​</a></h1><p>This directory provides source locations and notices for Expat, Emscripten runtime components, and Penrose optimizer with the registry crates in its fixed Cargo.lock. It is for users inspecting or redistributing the Lean image&#39;s browser components.</p><p>The records identify both linked components and build dependencies. For redistribution, use the component records together with the actual image contents and the separate Graphviz source materials in <code>graphviz-epl/</code>.</p><h2 id="expat" tabindex="-1">Expat <a class="header-anchor" href="#expat" aria-label="Permalink to &quot;Expat&quot;">​</a></h2><p><code>expat/LICENSE</code> and <code>expat/source.json</code> preserve the Expat 2.8.1 MIT text and source location. The fixed vcpkg port selects this version; the Graphviz payload contains the linked Expat component.</p><h2 id="emscripten" tabindex="-1">Emscripten <a class="header-anchor" href="#emscripten" aria-label="Permalink to &quot;Emscripten&quot;">​</a></h2><p><code>emscripten/notices/</code> contains the Emscripten 6.0.0 license, musl COPYRIGHT, and libc++ LICENSE.TXT from the fixed build input. Retain applicable runtime notices when distributing generated WebAssembly; the component record covers build inputs and leaves the exact linked runtime subset unspecified.</p><h2 id="penrose-optimizer" tabindex="-1">Penrose optimizer <a class="header-anchor" href="#penrose-optimizer" aria-label="Permalink to &quot;Penrose optimizer&quot;">​</a></h2><p><code>penrose-optimizer/LICENSE</code> preserves the Penrose MIT notice. <code>penrose-optimizer/build/</code> contains the fixed Cargo metadata. <code>penrose-optimizer/crates/</code> contains 46 per-crate directories with exact source URLs, archive hashes, license declarations, 77 original notice files, and 6 supplementary project notices.</p><p>The 46 crates cover the complete Cargo.lock, including build, host, and Windows-only dependencies. Their source records identify those roles. Supplementary notices are labeled separately from notices shipped in the crate archives.</p><h2 id="obtain-sources-and-retain-notices" tabindex="-1">Obtain sources and retain notices <a class="header-anchor" href="#obtain-sources-and-retain-notices" aria-label="Permalink to &quot;Obtain sources and retain notices&quot;">​</a></h2><p>Use the exact public URLs and hashes in each component record to obtain its source archives. This directory stores source metadata and notices. Follow each component&#39;s license when distributing binaries or corresponding source.</p><p>The fixed ProofWidgets npm dependency set is documented in <code>proofwidgets-npm/</code>. Include the applicable source materials and notices for all components of the containing image.</p>',13)])])}const u=t(r,[["render",a]]);export{h as __pageData,u as default};
